const data = $input.first().json;
const VERIFY_TOKEN = ($env.WHATSAPP_VERIFY_TOKEN || '').trim();
if (!VERIFY_TOKEN) return [{ json: { error: 'WHATSAPP_VERIFY_TOKEN nao configurado' } }];
if (data['hub.mode'] === 'subscribe' && data['hub.verify_token'] === VERIFY_TOKEN) {
  return [{ json: { challenge: data['hub.challenge'] } }];
}
return [{ json: { error: 'forbidden' } }];

// v21.0: Valida ambiente obrigatório no primeiro nó — falha rápida e explícita
const required = [
  'WHATSAPP_VERIFY_TOKEN',
  'WHATSAPP_PHONE_NUMBER_ID',
  'GOOGLE_SHEET_ID',
  'OPENAI_API_KEY',
  'CORRETOR_PHONE'
];
const missing = required.filter(k => !($env[k] || '').trim());
if (missing.length) {
  throw new Error('Variáveis de ambiente ausentes: ' + missing.join(', '));
}

// FIX #12: META_API_VERSION obrigatória — sem fallback silencioso para versão desatualizada
if (!($env.META_API_VERSION || '').trim()) {
  throw new Error('META_API_VERSION não configurada. Defina como v22.0 ou superior.');
}

return [{ json: $input.first().json }];

// v21.0: extração robusta de payload Meta
try {
  const data = $input.first().json;
  if (!data.entry?.[0]?.changes) return [{ json: { skip: true, reason: 'payload_invalido' } }];
  const change = data.entry[0].changes[0];
  if (!change.value.messages?.length) return [{ json: { skip: true, reason: 'status_update' } }];
  const msg = change.value.messages[0];
  const messageId = msg.id || '';
  const phone = change.value.contacts?.[0]?.wa_id || '';
  if (!phone) return [{ json: { skip: true, reason: 'phone_ausente' } }];
  if (!messageId) return [{ json: { skip: true, reason: 'message_id_ausente' } }];
  const timestamp = msg.timestamp
    ? new Date(Number(msg.timestamp) * 1000).toISOString()
    : new Date().toISOString();
  const type = msg.type;
  let content = '', mediaId = '';
  if (type === 'text') content = (msg.text?.body || '').trim().slice(0, 2000);
  else if (type === 'audio') mediaId = msg.audio?.id || '';
  else if (type === 'voice') mediaId = msg.voice?.id || '';
  else if (type === 'image') { mediaId = msg.image?.id || ''; content = (msg.image?.caption || '').slice(0, 200); }
  else if (type === 'document') content = '[cliente enviou documento]';
  else if (type === 'sticker') content = '[cliente enviou sticker]';
  else if (type === 'video') content = '[cliente enviou video]';
  else if (type === 'location') content = '[cliente enviou localizacao]';
  else content = '[tipo ' + type + ']';
  return [{ json: { phone, messageId, type, content, mediaId, timestamp, skip: false } }];
} catch(e) {
  return [{ json: { skip: true, reason: 'erro_extracao: ' + e.message } }];
}

// v21.0: Dedup atômico via Upstash Redis SET NX EX
// FIX #3: fallback Sheets REMOVIDO — dedup não-atômico dá falsa segurança.
// Se Redis cair, aceita mensagem (eventual duplicata rara > duplicata garantida com race condition).
const ctx = $input.first().json;
const messageId = ctx.messageId;
const UPSTASH_URL = ($env.UPSTASH_REDIS_URL || '').trim();
const UPSTASH_TOKEN = ($env.UPSTASH_REDIS_TOKEN || '').trim();

if (!UPSTASH_URL || !UPSTASH_TOKEN) {
  // Redis não configurado: aceita mensagem, loga warning
  console.log('[DEDUP-WARN] Redis não configurado. Dedup desativado — risco de duplicata baixo.');
  return [{ json: { ...ctx, skip: false, dedupMode: 'disabled' } }];
}

try {
  const redisKey = `dedup:msg:${messageId}`;
  const response = await $helpers.httpRequest({
    method: 'POST',
    url: `${UPSTASH_URL}/set/${encodeURIComponent(redisKey)}/1/nx/ex/86400`,
    headers: { 'Authorization': `Bearer ${UPSTASH_TOKEN}` }
  });
  if (response?.result !== 'OK') {
    return [{ json: { ...ctx, skip: true, reason: 'dedup_redis_duplicata', dedupMode: 'redis' } }];
  }
  return [{ json: { ...ctx, skip: false, dedupMode: 'redis' } }];
} catch(e) {
  // Redis com erro: aceita mensagem com log — melhor eventual duplicata que falsa segurança
  console.log('[DEDUP-ERROR] Redis falhou, aceitando mensagem: ' + e.message);
  return [{ json: { ...ctx, skip: false, dedupMode: 'redis_error', dedupRedisErro: e.message } }];
}

// v21.0 FIX #2/#4: propaga contexto original como _msgCtx.
// Entrada: item de 4b (branch FALSE = sem mediaId), contém phone/messageId/type/timestamp.
const ctx = $input.first().json;
return [{ json: {
  _msgCtx: {
    phone: ctx.phone,
    messageId: ctx.messageId,
    type: ctx.type,
    timestamp: ctx.timestamp
  },
  content: '[cliente enviou audio mas mediaId ausente — não foi possível processar]',
  mediaId: ''
} }];

// v21.0 FIX #2: salva contexto original em _msgCtx ANTES de qualquer chamada externa.
// Downstream (incluindo error paths) sempre tem acesso via item._msgCtx, sem cross-node lookup.
const ctx = $input.first().json;
return [{ json: {
  _msgCtx: {
    phone: ctx.phone,
    messageId: ctx.messageId,
    type: ctx.type,
    timestamp: ctx.timestamp
  },
  mediaId: ctx.mediaId
} }];

// onError de node5: N8N passa o item de entrada (output de node4d = {_msgCtx, mediaId})
const item = $input.first().json;
const msgCtx = item._msgCtx || {};
console.error('[AUDIO-URL-ERROR] Falha Meta API.');
return [{ json: { _msgCtx: msgCtx, content: '[audio: URL Meta indisponível]' } }];

const item=$input.first().json;
const msgCtx=$('4d.Preparar Contexto Audio').first().json._msgCtx||{};
if(!item.url) return [{json:{_msgCtx:msgCtx,content:'[audio: URL não retornada pela Meta API]'}}];
return [{json:{_msgCtx:msgCtx,audioUrl:item.url,mediaId:item.id||''}}];

// Unico ponto $('4d') na branch principal (node8 é o outro, inevitavel por Whisper substituir json)
const item = $input.first();
const msgCtx = $('4d.Preparar Contexto Audio').first().json._msgCtx || {};
const b64 = item.binary?.data?.data || '';
const sizeBytes = b64 ? Math.ceil((b64.length * 3) / 4) : 0;
if (sizeBytes > 25 * 1024 * 1024) {
  console.log('[AUDIO-WARN] Arquivo >25MB, pulando Whisper.');
  return [{ json: { _msgCtx: msgCtx, content: '[audio muito grande para transcrever]' } }];
}
// Restaura _msgCtx no json para node7b poder usar item._msgCtx no error path
return [{ json: { _msgCtx: msgCtx }, binary: item.binary }];

// onError de node6: N8N passa o item de entrada (output de node5b = {_msgCtx, audioUrl})
const item = $input.first().json;
const msgCtx = item._msgCtx || {};
return [{ json: { _msgCtx: msgCtx, content: '[audio: download falhou — não foi possível transcrever]' } }];

// input ao Whisper = output de node6v = {json:{_msgCtx}, binary}
// N8N onError passa o input item → item._msgCtx disponivel
const item = $input.first().json;
const msgCtx = item._msgCtx || {};
const content = item.content || '[audio: transcrição Whisper falhou]';
return [{ json: { _msgCtx: msgCtx, content } }];

try{
  const item=$input.first().json;
  const msgCtx=$('4d.Preparar Contexto Audio').first().json._msgCtx||{};
  const transcricao=(item.text||'[audio sem transcrição]').slice(0,1000);
  return [{json:{_msgCtx:msgCtx,content:'[Audio]: '+transcricao}}];
}catch(e){
  const msgCtx=$('4d.Preparar Contexto Audio').first().json._msgCtx||{};
  return [{json:{_msgCtx:msgCtx,content:'[audio erro: '+e.message+']'}}];
}

// v21.0 FIX #2/#4: consolida audio de volta para o fluxo principal.
// Aceita _msgCtx de item.json (propagado por 4c, 5e, 6e, 7b, 8).
const item = $input.first().json;
const msgCtx = item._msgCtx || {};
if (!msgCtx.phone) throw new Error('8b: _msgCtx.phone ausente.');
return [{ json: {
  phone: msgCtx.phone,
  messageId: msgCtx.messageId,
  type: msgCtx.type || 'audio',
  msg: item.content || '[audio]',
  mediaId: '',
  timestamp: msgCtx.timestamp,
  skip: false
} }];

// v21.0: imagem — solicita descrição em texto ao cliente.
const ctx = $input.first().json;
const legenda = ctx.content ? ' Legenda: ' + ctx.content : '';
return [{ json: {
  phone: ctx.phone,
  messageId: ctx.messageId,
  type: ctx.type,
  msg: '[Cliente enviou imagem.' + legenda + ' Peça para descrever em texto o imóvel que procura.]',
  mediaId: '',
  timestamp: ctx.timestamp,
  skip: false
} }];

// v21.0: texto e outros tipos — passa diretamente para 10b.
const ctx = $input.first().json;
return [{ json: {
  phone: ctx.phone,
  messageId: ctx.messageId,
  type: ctx.type,
  msg: ctx.content || '',
  mediaId: '',
  timestamp: ctx.timestamp,
  skip: false
} }];

// v21.0 FIX #1: ponto de convergência de todas as rotas (texto, imagem, audio).
// Valida que phone e msg chegaram corretamente antes de continuar.
const ctx = $input.first().json;
if (!ctx.phone) throw new Error('10b: phone ausente. Keys: ' + JSON.stringify(Object.keys(ctx)));
if (ctx.msg === undefined) throw new Error('10b: campo msg ausente');
return [{ json: ctx }];

// v21.0: prepara contexto do lead para o GPT.
// Aceita múltiplos itens do Sheets (dedup de linhas duplicadas por data mais recente).
const allItems = $input.all();
const first = allItems[0]?.json || {};
const phone = first.phone || '';
const msg = (first.msg || '').slice(0, 2000);
const timestamp = first.timestamp || new Date().toISOString();
const messageId = first.messageId || '';
if (!phone) throw new Error('11b: phone ausente.');
const isNovo = !first.Telefone;
const status = isNovo ? 'NOVO' : (first.Status || 'NOVO');
const score = isNaN(Number(first.Score)) ? 0 : Math.min(100, Math.max(0, Number(first.Score)));
const tentativas = Number(first.Tentativas_Pos_Entrega) || 0;
const resumo = (first.Resumo || '').slice(0, 300);
let historicoRaw = (first.Historico || '').replace(/[\u0000-\u001F\u007F]/g, ' ');
if (historicoRaw.length > 6000) historicoRaw = historicoRaw.slice(-6000).replace(/^[^\n]*\n/, '');
if (allItems.length > 1) {
  const rec = allItems.reduce((a, b) => new Date(a.json.ULTIMA_MSG || 0) > new Date(b.json.ULTIMA_MSG || 0) ? a : b).json;
  historicoRaw = (rec.Historico || '').replace(/[\u0000-\u001F\u007F]/g, ' ');
  if (historicoRaw.length > 6000) historicoRaw = historicoRaw.slice(-6000).replace(/^[^\n]*\n/, '');
}
return [{ json: { status, historicoRaw, score, isNovo, tentativas, phone, msg, timestamp, messageId, resumo } }];

// v21.0: Sheets inacessível — cria contexto de lead novo com log de erro.
const ctx = $input.first().json;
console.error('[CRM-ERROR] Sheets inacessível para: ' + (ctx.phone || '?'));
return [{ json: {
  status: 'NOVO',
  historicoRaw: '',
  score: 0,
  isNovo: true,
  tentativas: 0,
  phone: ctx.phone || '',
  msg: ctx.msg || '',
  timestamp: ctx.timestamp || new Date().toISOString(),
  messageId: ctx.messageId || '',
  resumo: '',
  _sheetsError: true
} }];

const ctx = $input.first().json;
return [{ json: {
  _reopenCtx: {
    phone:     ctx.phone,
    msg:       ctx.msg,
    timestamp: ctx.timestamp,
    messageId: ctx.messageId
  },
  ...ctx
} }];

// Sheets substituiu item.json pelos dados gravados (nomes das colunas)
// _reopenCtx preserva phone, msg, timestamp, messageId originais
const saved = $('13c_p.Salvar Ctx Reabrir').first().json._reopenCtx || {};
return [{ json: {
  phone:       saved.phone     || '',
  msg:         saved.msg       || '',
  timestamp:   saved.timestamp || new Date().toISOString(),
  messageId:   saved.messageId || '',
  status:      'NOVO',
  historicoRaw: '',
  score:       0,
  tentativas:  0,
  isNovo:      true,
  resumo:      ''
} }];

const ctx = $input.first().json;
return [{ json: {
  _newCtx: {
    phone:     ctx.phone,
    msg:       ctx.msg,
    timestamp: ctx.timestamp,
    messageId: ctx.messageId
  },
  ...ctx
} }];

// Sheets substituiu item.json pelos dados gravados (nomes das colunas)
// _newCtx preserva phone, msg, timestamp, messageId originais
const saved = $('15b_p.Salvar Ctx Novo Lead').first().json._newCtx || {};
return [{ json: {
  phone:        saved.phone     || '',
  msg:          saved.msg       || '',
  timestamp:    saved.timestamp || new Date().toISOString(),
  messageId:    saved.messageId || '',
  status:       'NOVO',
  historicoRaw: '',
  score:        0,
  isNovo:       true,
  tentativas:   0,
  resumo:       ''
} }];

const ctx=$input.first().json;
if(!ctx.phone||ctx.msg===undefined) throw new Error('15d: phone ou msg ausente');
return [{json:ctx}];

// v21.0 FIX #6 e #10:
// FIX #10: systemPrompt lido de variável de ambiente GPT_SYSTEM_PROMPT se disponível.
//           Permite corretor ajustar regras de negócio sem editar workflow.
// FIX #6: rate limit 5s POR TELEFONE — mensagens descartadas silenciosamente.
//         SOLUÇÃO: rate limit reduzido para 1s (GPT-4o-mini é rápido) e
//         mensagens em burst são aceitas e processadas em sequência.
//         Se rate limited, retorna flag para enqueueing futuro (não descarta).

try {
  const ctx = $input.first().json;

  const UPSTASH_URL = ($env.UPSTASH_REDIS_URL || '').trim();
  const UPSTASH_TOKEN = ($env.UPSTASH_REDIS_TOKEN || '').trim();
  if (UPSTASH_URL && UPSTASH_TOKEN) {
    const rlKey = `ratelimit:phone:${ctx.phone}`;
    const rlResp = await $helpers.httpRequest({
      method: 'POST',
      // FIX #6: janela reduzida de 5s para 1s — GPT-4o-mini processa em ~500ms
      url: `${UPSTASH_URL}/set/${encodeURIComponent(rlKey)}/1/nx/ex/1`,
      headers: { 'Authorization': `Bearer ${UPSTASH_TOKEN}` }
    });
    if (rlResp?.result !== 'OK') {
      // FIX #6: não descarta — retorna rateLimited=true com contexto para 17b poder responder
      return [{ json: {
        _ctx: { ...ctx },
        _gptRaw: JSON.stringify({
          resposta: 'Recebi sua mensagem! Aguarde um instante que já estou processando... 😊',
          score: ctx.score || 0,
          quente: (ctx.score || 0) >= 80,
          resumo: ctx.resumo || '',
          rateLimited: false
        })
      } }];
    }
  }

  // FIX #10: systemPrompt customizável via env, com fallback robusto
  const customPrompt = ($env.GPT_SYSTEM_PROMPT || '').trim();
  const systemPrompt = customPrompt || `Você é a assistente virtual de um corretor autônomo de imóveis em Aracaju/SE. Seja educada, natural e NUNCA revele que é IA. Só fale sobre imóveis.

REGRAS ABSOLUTAS:
- Máximo 2 perguntas por mensagem
- Português brasileiro natural
- Sem links desnecessários
- Se imagem: peça para descrever em texto
- Se off-topic: redirecione gentilmente
- Retorne APENAS o objeto JSON abaixo, sem texto fora, sem markdown

PERGUNTAS DE QUALIFICAÇÃO (uma por vez, na ordem):
1. Tipo de imóvel? (casa, apartamento, terreno, comercial)
2. Bairro preferido em Aracaju?
3. Orçamento aproximado?
4. Prazo para fechar negócio?
5. Financiamento ou à vista?

SCORE ATUAL DO LEAD: ${ctx.score}/100
REGRA DE SCORE: NUNCA retorne score menor que ${ctx.score}. Some ao score atual, nunca substituta.

RESUMO ATUAL: ${ctx.resumo || 'Sem resumo ainda.'}
REGRA DE RESUMO: acumule informações no resumo, não substitua do zero.

SCORING INCREMENTAL (some ao score atual):
- Orçamento > R$500k: +30
- Prazo < 90 dias: +40
- Pediu visita ou proposta: +30
- Bairro nobre (Jardins, Atalaia, Ponta da Terra, 13 de Julho): +20
- À vista: +20
- Já visitou imóvel: +15

Se score >= 80 OU cliente pediu visita/proposta: quente=true.

FORMATO OBRIGATÓRIO (JSON puro, sem markdown, sem texto fora do JSON):
{"resposta": "Mensagem ao cliente", "score": 45, "quente": false, "resumo": "Perfil em uma frase"}`;

  const userPrompt = `Histórico:\n${ctx.historicoRaw || ''}\n\n---\nNova mensagem do cliente:\n${ctx.msg || 'Olá'}`;

  let response;
  let tentativasAPI = 0;
  const MAX_TENTATIVAS = 3;
  while (tentativasAPI < MAX_TENTATIVAS) {
    try {
      response = await $helpers.httpRequest({
        method: 'POST',
        url: 'https://api.openai.com/v1/chat/completions',
        headers: { 'Authorization': `Bearer ${$env.OPENAI_API_KEY}`, 'Content-Type': 'application/json' },
        body: {
          model: 'gpt-4o-mini',
          response_format: { type: 'json_object' },
          messages: [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: userPrompt }
          ]
        }
      });
      break;
    } catch(apiErr) {
      tentativasAPI++;
      if (tentativasAPI === MAX_TENTATIVAS) throw apiErr;
      await new Promise(r => setTimeout(r, 1000 * Math.pow(2, tentativasAPI - 1)));
    }
  }

  const rawContent = response.choices?.[0]?.message?.content || '{}';
  return [{ json: { _ctx: { ...ctx }, _gptRaw: rawContent } }];

} catch(e) {
  const ctx = $input.first().json;
  const scoreSalvo = ctx.score || 0;
  return [{ json: {
    _ctx: { ...ctx },
    _gptRaw: JSON.stringify({ resposta: 'Como posso te ajudar a encontrar um imóvel em Aracaju?', score: scoreSalvo, quente: scoreSalvo >= 80, resumo: ctx.resumo || '' })
  } }];
}

try{
  const input=$input.first().json;
  const ctx=input._ctx;
  const raw=input._gptRaw||'{}';
  let p;
  try{p=JSON.parse(raw);}catch(e1){const m=raw.match(/\{[\s\S]*?\}/);if(m){try{p=JSON.parse(m[0]);}catch(e2){p=null;}}}
  if(!p||typeof p!=='object') p={resposta:'Olá! Posso te ajudar.',score:0,quente:false,resumo:'erro_parse'};
  if(typeof p.resposta!=='string'||!p.resposta.trim()) p.resposta='Como posso te ajudar?';
  if(typeof p.score!=='number'||isNaN(p.score)) p.score=ctx.score||0;
  if(typeof p.quente!=='boolean') p.quente=false;
  if(typeof p.resumo!=='string') p.resumo=ctx.resumo||'';
  const scoreNovo=Math.min(100,Math.max(Number(ctx.score)||0,Number(p.score)||0));
  const quente=p.quente===true||scoreNovo>=80;
  return [{json:{phone:ctx.phone,msg:ctx.msg,timestamp:ctx.timestamp,historicoRaw:ctx.historicoRaw,score:scoreNovo,tentativas:ctx.tentativas||0,resposta:p.resposta.slice(0,1500),quente,resumo:(p.resumo||ctx.resumo||'').slice(0,300),isNovo:ctx.isNovo||false,rateLimited:false}}];
}catch(e){
  const ctx=$input.first().json._ctx||{};
  const s=Number(ctx.score)||0;
  return [{json:{phone:ctx.phone||'',msg:ctx.msg||'',timestamp:ctx.timestamp||new Date().toISOString(),historicoRaw:ctx.historicoRaw||'',score:s,tentativas:ctx.tentativas||0,resposta:'Olá!',quente:s>=80,resumo:ctx.resumo||'',rateLimited:false}}];
}

const ctx = $input.first().json;
return [{ json: {
  _hotCtx: {
    phone:   ctx.phone,
    score:   ctx.score,
    resumo:  ctx.resumo,
    msg:     ctx.msg,
    timestamp: ctx.timestamp
  },
  ...ctx
} }];

// node23 (Sheets) substituiu item.json por colunas da planilha
// _hotCtx preserva phone, score, resumo originais do lead quente
const saved = $('23_p.Salvar Ctx Handover').first().json._hotCtx || {};
const phone = saved.phone || '';
if (!phone) throw new Error('22g: phone ausente no _hotCtx');
const CORRETOR_PHONE = ($env.CORRETOR_PHONE || '').trim();
if (!CORRETOR_PHONE) throw new Error('CORRETOR_PHONE nao configurado');
return [{ json: {
  phone:        phone,
  score:        saved.score   || 0,
  resumo:       saved.resumo  || '',
  msg:          saved.msg     || '',
  timestamp:    saved.timestamp || new Date().toISOString(),
  corretorPhone: CORRETOR_PHONE
} }];

// Envio WhatsApp falhou — garante que o histórico seja salvo no CRM
console.warn('[WA-WARN] Falha ao enviar resposta ao cliente. Salvando histórico.');
return [{ json: $input.first().json }];
